mapper.select:
select e.escrow_id, e.escrow_no, e.order_id, e.amount, e.paid_at, e.pay_channel, e.status, e.release_time, e.release_reason, e.refund_amount, e.refunded_at, e.created_at, e.updated_at, o.order_no, w.title as work_title, o.buyer_id, o.seller_id, ub.nick_name as buyer_name, us.nick_name as seller_name from sys_escrow e left join sys_order o on e.order_id = o.order_id left join sys_work w on o.work_id = w.work_id left join sys_user ub on o.buyer_id = ub.user_id left join sys_user us on o.seller_id = us.user_id
AND e.status = #{status} AND e.order_id = #{orderId} AND o.buyer_id = #{buyerId} AND o.seller_id = #{sellerId}
order by e.created_at desc

mapper.insert:
insert into sys_escrow (
    escrow_no, order_id, amount, paid_at, pay_channel, status,
    release_time, release_reason, remark, create_by, create_time
) values (
    #{escrowNo}, #{orderId}, #{amount}, #{paidAt}, #{payChannel}, #{status},
    #{releaseTime}, #{releaseReason}, #{remark}, #{createBy}, #{createTime}
)

mapper.update:
update sys_escrow
status = #{status}, release_time = #{releaseTime}, release_reason = #{releaseReason}, refund_amount = #{refundAmount}, refunded_at = #{refundedAt}, update_by = #{updateBy}, update_time = #{updateTime},
where escrow_id = #{escrowId}
